Belvedere is planning to upgrade its MagicNumberService. This service keeps track of the maximum
"magic number" that it has seen, and services requests as follows:
 - Receives a serialized MagicNumberServiceRequest
 - Deserializes the request
 - Performs a computationally-intensive algorithm to generate the "magic number" for that
 request
 - Updates its maximum "magic number" if the generated "magic number" is greater
 - Constructs a MagicNumberServiceResponse, setting the DidChangeMax parameter according to
 whether the maximum "magic number" was updated
 - Serializes the response
 - Sends the response on the same connection it received the request on

Currently, the MagicNumberService is single-threaded, causing a bottleneck. You must upgrade it
to take advantage of multi-threading, subject to the following constraints:
 - The SequenceNumbers of sequential received requests must increase monotonically; any received
 requests that don't follow this pattern should not be responded to.
 - Requests must be serviced (i.e., must affect the maximum magic number) in the order they
 were received.

Note that only one MagicNumberService will exist at a time. Also note that some back-end "implementation details" are provided to you. These are only included so
that intellisense works properly in the testing environment. They do not reflect how these
features would actually be implemented, and should not be modified.

using System;

namespace MagicNumberService
{
 class MagicNumberService
 {
 private long \_nextSequenceNumber = 0;
 private long \_maxMagicNumber = 0;
 private SocketWrapper \_socketWrapper;
 private SourceOfMagic \_sourceOfMagic;

 private void HandleRequest(int connectionId, byte[] bytes)
 {
 var request = MagicNumberServiceRequest.FromSerializedBytes(bytes);
 if (request.SequenceNumber < \_nextSequenceNumber)
 {
 return;
 }
 \_nextSequenceNumber = request.SequenceNumber + 1;

 long requestMagicNumber = \_sourceOfMagic.GetMagicNumberForRequest(request); // Depends only on "request"; takes ~3 seconds
 bool didMaxChange = requestMagicNumber > \_maxMagicNumber;
 var response = new MagicNumberServiceResponse(requestMagicNumber, didMaxChange);
 \_maxMagicNumber = didMaxChange ? requestMagicNumber : \_maxMagicNumber;
 \_socketWrapper.Send(connectionId, response.SerializeToBytes());

 }

 public void Run()
 {
 while (true)
 {
 int connectionId = \_socketWrapper.Receive(out byte[] bytes); // Blocks until a request is received
 HandleRequest(connectionId, bytes);
 }
 }

 public MagicNumberService(SocketWrapper socketWrapper, SourceOfMagic sourceOfMagic)
 {
 \_socketWrapper = socketWrapper;
 \_sourceOfMagic = sourceOfMagic;
 }
 }

 ///////////////////////////////////////////////////////////////////////////////////////////
 // =========================== DO NOT MODIFY BELOW THIS LINE =========================== //
 ///////////////////////////////////////////////////////////////////////////////////////////

 class MagicNumberServiceRequest
 {

 public long SequenceNumber { get; }
 // ... Other fields required for the GetMagicNumberForRequest() function

 public static MagicNumberServiceRequest FromSerializedBytes(byte[] bytes)
 {
 return new MagicNumberServiceRequest(bytes);
 }
 public byte[] SerializeToBytes()
 {
 return BitConverter.GetBytes(SequenceNumber);
 }
 private MagicNumberServiceRequest(byte[] bytes)
 {
 SequenceNumber = BitConverter.ToInt64(bytes);
 }
 }

 class MagicNumberServiceResponse
 {
 public long SequenceNumber { get; }
 public bool DidMaxChange { get; }

 public byte[] SerializeToBytes()
 {
 var result = new byte[sizeof(long) + sizeof(bool)];
 BitConverter.GetBytes(SequenceNumber).CopyTo(result, 0);
 BitConverter.GetBytes(DidMaxChange).CopyTo(result, sizeof(long));
 return result;
 }
 public static MagicNumberServiceResponse FromSerializedBytes(byte[] bytes)
 {
 return new MagicNumberServiceResponse(bytes);
 }

 public MagicNumberServiceResponse(long sequenceNumber, bool didMaxChange)
 {
 SequenceNumber = sequenceNumber;
 DidMaxChange = didMaxChange;
 }

 private MagicNumberServiceResponse(byte[] bytes)
 {
 SequenceNumber = BitConverter.ToInt64(bytes, 0);
 DidMaxChange = BitConverter.ToBoolean(bytes, sizeof(long));
 }
 }

 abstract class SocketWrapper
 {
 public abstract int Receive(out byte[] bytes);
 public abstract void Send(int connectionId, byte[] bytes);
 }

 abstract class SourceOfMagic
 {
 public abstract long GetMagicNumberForRequest(MagicNumberServiceRequest request);
 }

