type ExpandColOp interface {

 //dataVal 指向原始模型结构数据的指针
 //dbfieldName 结构体字段名StructField name，多层时用"."连接
 //存入数据库时调用，把结构体内的原始值转换成数据库即将存入的值
 GetFieldDbValue(dataVal reflect.Value, dbfieldName string) (interface{}, error)

 //dataVal 指向原始模型结构数据的指针
 //dbfieldName 结构体字段名StructField name，多层时用"."连接
 //从数据库读取时调用，把数据库中列值转换为结构体内field数据
 FillFieldByDbValue(dataVal reflect.Value, dbfieldName string, FieldDbVal interface{}) error
}

type CovertExpandCols interface {

 //dataVal 指向原始模型结构数据的指针
 //inputField 结构体字段名以及其底层递归名 或者 dbName
 //orm内部对各接口输入的列进行调用此函数转化为对应的列FieldName,列对应值为nil已过滤
 //error:当数组长度为0时，会返回error
 ReadParamFilter(dataVal reflect.Value, inputField string) ([]string, error)

 //dataVal 指向原始模型结构数据的指针
 //inputField 结构体字段名以及其底层递归名 或者 dbName
 //orm内部对各接口输入的列进行调用此函数转化为对应的列FieldName,列对应值为nil不会过滤
 //error:当数组长度为0时，会返回error
 ReadParamAllFilter(dataVal reflect.Value, inputField string) ([]string, error)

 //modelVal 指向原始模型结构数据指针，供插件读出模型类型
 //dataVal 指向原始模型结构数据的指针，包含列值
 //ormReadField 结构体字段名以及其底层递归名 或者 dbName
 //orm内部对各接口输入的列以及列值进行调用此函数转化为对应的列FieldName与数据库存入值,列对应值为nil已过滤
 //error:当map长度为0时，会返回error
 QsReadParamFilter(modelVal interface{}, dataVal reflect.Value, ormReadField string) (dataVals map[string]interface{}, e error)

 //modelVal 指向原始模型结构数据指针，供插件读出模型类型
 //dataVal 指向原始模型结构数据的指针，包含列值
 //ormReadField 结构体字段名以及其底层递归名 或者 dbName
