 //error:当map长度为0时，会返回error
 QsUpdateFilter(modelVal interface{}, dataVal reflect.Value, ormReadField string) (dataVals map[string]interface{}, e error)
}

type ColumnDesc struct {
 FieldName string //在模型数据结构里面的字段名
 DbName string //在DB 里面的列名
 ColType DbColumnColType //对应的列类型
 IsJson bool //嵌套类型描述，sql数据库存成json字符串，Mongo依赖其自身特性
